static SynurangLiteStatus volvoxai_runtime_cross_entropy_loss_encode_into(
    const VolvoxaiRuntimeCrossEntropyLoss* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_name.len) {
        sl_write_length_delimited(
            writer,
            1,
            message->field_name.data,
            message->field_name.len);
    }
    if (message->field_logits_name.len) {
        sl_write_length_delimited(
            writer,
            2,
            message->field_logits_name.data,
            message->field_logits_name.len);
    }
    if (message->field_targets.len) {
        SynurangLiteWriterInternal packed;
        sl_writer_init(&packed, message->_allocator);
        for (i = 0; i < message->field_targets.len; ++i) {
            sl_write_int32_raw(
                &packed, message->field_targets.data[i]);
        }
        if (packed.status == SYNURANG_LITE_OK) {
            sl_write_length_delimited(writer, 3, packed.data, packed.len);
        }
        status = packed.status;
        sl_writer_discard(&packed);
        if (status != SYNURANG_LITE_OK) return status;
    }
    if (message->has_ignore_index) {
        sl_write_int32(
            writer, 4, message->field_ignore_index);
    }
    if (message->has_row_index) {
        sl_write_int32(
            writer, 5, message->field_row_index);
    }
    if (message->has_weight) {
        sl_write_float(
            writer, 6, message->field_weight);
    }
    if (message->field_normalizer != 0) {
        sl_write_float(
            writer, 7, message->field_normalizer);
    }
    (void)i;
    return writer->status;
}

