                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_shape.data,
                            &message->field_shape.len,
                            &message->field_shape.cap,
                            sizeof(*message->field_shape.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int64_raw(
                                &packed,
                                (int64_t*)appended)) break;
